/**
 * Emits `overlay-click` on the overlay bus for pointer interactions inside a portaled overlay popup.
 *
 * Bound natively in the capture phase: a React synthetic handler on a portaled popup runs after the
 * `document`-level listener that consumers (see `usePopover`) dismiss on, and would lose that race.
 *
 * @param popupElement The overlay popup element, tracked in state so the effect re-runs on mount.
 * @param getTarget Returns the element reported as the overlay's owner, usually its root element.
 */
export declare function useOverlayClickEmitter(popupElement: HTMLElement | null | undefined, getTarget: () => Element | null | undefined): void;
